var e="/brand",a={seo:{title:"Brand and design system",description:"The mhfrough design system, documented live: the hamza mark, monochrome color tokens, the Geist type scale, shape and spacing rules, components, motion and accessibility."},hero:{tag:"Design system",pill:"Monochrome, dark only",line1:"mhfrough's system.",line2:"Black and white.",lede:"The design language of mhfrough.dev. Dark only, two inks, one shape rule. Every specimen below renders the live code.",browse:"Browse components",download:"Download the mark"},inspector:{title:"Token inspector",groups:"Token group",tokens:"Tokens",on:"on",copy:"Copy",copied:"Copied",copiedLive:"Copied to clipboard"},toc:{label:"On this page"},spec:{copy:"Copy markup",copied:"Copied",copiedLive:"Markup copied to clipboard"},logo:{title:"The hamza mark",sub:"The mark is the Arabic letter hamza (\u0621), the first letter of Hamza, drawn from two primitives on a 48 unit grid. It always sits on the brand tile: a circle filled with --cta, inside a pill in the nav and footer.",sizes:"Sizes",sizesNote:"The tile radius scales with the tile (10 / 34). The mark fills 65% of the tile.",lockup:"Lockup",lockupNote:"Tile, name in Geist 600, handle in Geist Mono. Name and handle never change order.",construction:"Construction",constructionNote:"Never redraw it by eye. Both shapes come from logo.ts (MARK_ARC, MARK_TAIL).",show:"Show",downloads:"Downloads",downloadsNote:"SVG, generated from the same geometry.",min:"Minimum size 16px. Below that use the favicon.",rules:[{k:"Grid",v:"48 x 48 units"},{k:"Arc",v:"centre c (24.5, 21), r 8, stroke 5"},{k:"Sweep",v:"225 degrees, from -45 to 90"},{k:"Tail",v:"base line y 26.5 to x 37, tapering down-left to a 3 unit point at (15.5, 38)"},{k:"Bounds",v:"23 x 27.5, from (14, 10.5), optically centred"},{k:"Clear space",v:"10 units (two strokes) each side"},{k:"Minimum",v:"16px"}],files:[{href:"/images/brand/mark-tile.svg",name:"mark-tile.svg",note:"Dark on light, the default tile"},{href:"/images/brand/mark-tile-dark.svg",name:"mark-tile-dark.svg",note:"Light on dark"},{href:"/images/brand/mark.svg",name:"mark.svg",note:"Mark only, dark ink"},{href:"/images/brand/mark-light.svg",name:"mark-light.svg",note:"Mark only, light ink"}]},color:{title:"Two inks, many greys",sub:"The palette is monochrome on purpose. The accent is the ink itself, so anything that needs attention inverts: CTAs, pressed chips and the brand tile use a light fill with dark text.",themes:{title:"Case-study themes",note:"Each case study wears its product\u2019s colors and nothing else. A theme overrides these same tokens under :root[data-theme], so nav, footer and page change together, while type, radii and components stay. Ratios are ink on the page and the CTA label on its fill.",text:"Text",cta:"CTA",open:"case study"},ratio:"Ratio",shadows:"Shadows",live:"Values and ratios are read from the page as it renders."},type:{title:"Geist, set tight",sub:"Two families: Geist Variable for everything people read, Geist Mono Variable for what machines read. Big type is tracked tight, small type is left alone.",sans:"Geist Variable",sansNote:"UI and prose. Weights 400, 500, 600.",mono:"Geist Mono Variable",monoNote:"Commands, metadata, numbers.",scale:"The scale",now:"now",monoRules:"When to use mono",monoList:["Commands and code: the .cmd bar, .code blocks, inline code.","Metadata: dates, versions, durations, file names, the handle.","Numbers that line up: counts, timestamps, ratios.","Small captions under specimens and reels.","Never for headlines, buttons or running prose."]},shape:{title:"Pills, cards, wells",sub:"One shape rule: anything you can press is a full pill, containers are 16px cards, and anything nested inside a card is 12px.",shapeRule:"The shape rule",nesting:[{cls:"--r-pill",v:"999px",what:"Buttons, chips, badges, tabs, inputs"},{cls:"--r-card",v:"16px",what:"Cards, panels, menus, reels"},{cls:"--r-inner",v:"12px",what:"Code blocks, textareas, nested blocks"}],space:"Spacing rhythm",spaceNote:"Few distances, used everywhere. Bars are drawn at true size.",spacing:[{k:"Section padding",v:88,m:"64px under 768px"},{k:"Head to content",v:36,m:"title block to first card"},{k:"Hero top clearance",v:56,m:"below the floating nav"},{k:"Card padding",v:22,m:".card, .panel"},{k:"Gutter",v:24,m:"16px under 640px",token:"--gutter"},{k:"Grid gap",v:10,m:"bento and card grids"},{k:"Chip gap",v:6,m:"badges, tags, presets"}],elevation:"Elevation",elevationNote:"Two shadows. Flat by default, lift on hover, shadow-lg for the one hero card.",flat:"Flat",flatNote:"Default. Border only.",hover:"Hover me",glass:"Glass",glassNote:"Blur 18px, saturate 1.6, surface at 62%. Falls back to solid --surface when transparency is reduced or backdrop-filter is missing.",glassBrand:"Mohammad Hamza",z:"Layers",zNote:"Three z-index tokens. Nothing else sets z-index above 1.",zTokens:[{name:"--z-nav",v:"20",what:"Floating nav"},{name:"--z-overlay",v:"40",what:"Menus and overlays"},{name:"--z-skip",v:"100",what:"Skip link"}]},components:{title:"Components",sub:"Global classes from _components.scss. Pages compose them and never redefine them. Each specimen is the real class; copy its markup straight from the render.",groups:{actions:{title:"Actions",sub:"Buttons, links and toggles. All pills, all 40px or taller."},pills:{title:"Chips, badges, tags",sub:"Chips toggle with aria-pressed. Badges and tags only label."},code:{title:"Commands and code",sub:"Solid blocks with a copy button."},surfaces:{title:"Cards",sub:"One surface, four treatments. Bento grids mix plain and solid cells, and a project\u2019s own mark replaces its icon."},forms:{title:"Forms",sub:"Label above, hint and error below, error linked with aria-describedby."},status:{title:"Media and loading",sub:"Skeletons and reels. Skeletons match the final shape; never a spinner."}}},motion:{title:"Motion on content",sub:"Motion follows reading order: the headline rises, the rest fades up, sections reveal as they arrive. Transform and opacity only.",tokens:"Tokens",demos:"Live demos",replay:"Replay",reduced:"Reduced motion is on. Demos show their end state, as the site does.",rules:"Rules",ruleList:["Motion belongs to content: headlines, cards, sections. Never to the pointer.","No custom cursor. No magnetic buttons. No animated link underlines.","No big footer CTA text.","Transform and opacity only. Looping animations pause off screen.","Every animation sits behind prefers-reduced-motion: no-preference.","One marquee per page, at most."],durations:[{name:"--t-fast",v:"0.2s",what:"Color, small presses"},{name:"--t-base",v:"0.25s",what:"Buttons, chips, borders"},{name:"--t-slow",v:"0.8s",what:"Rise and reveal"},{name:"line rise",v:"1s",what:"Hero .line spans, +0.09s for line two"},{name:"stagger",v:"55ms",what:"Per [revealIndex] step"}],eases:[{name:"--ease",v:"cubic-bezier(0.16, 1, 0.3, 1)",what:"Everything that enters",p:[.16,1,.3,1]},{name:"--ease-in-out",v:"cubic-bezier(0.65, 0, 0.35, 1)",what:"Things that move across",p:[.65,0,.35,1]}]},icons:{title:"Phosphor, regular",sub:"One icon family, one weight. Icons come from @ng-icons/phosphor-icons/regular and are registered per component. Never hand-draw an icon.",sizes:"Sizes",usage:"Usage",rules:['Decorative icons get aria-hidden="true". The button or link carries the name.',"Icon-only buttons need aria-label.","Icons take currentColor; never color them separately.","UI icons are Phosphor only. Custom drawing is limited to the hamza mark and portfolio artwork such as the weather icon set on /work, which is never used as UI."]},voice:{title:"Plain, exact, short",sub:"Copy is written like a commit message from someone senior: facts first, no hype, nothing the CV cannot back.",ctas:"One label per intent",ctasNote:"The same action always reads the same, on every page.",ctaList:[{intent:"See the portfolio",label:"View work"},{intent:"Hire information",label:"Hire me"},{intent:"Start a conversation",label:"Get in touch"},{intent:"Submit the contact form",label:"Send message"}],rules:[{k:"No em or en dashes",v:"Use a comma, a colon or a full stop. U+2014 and U+2013 never ship."},{k:"No filler verbs",v:"Say what it does. Words like elevate, seamless and unleash are out."},{k:"Facts only",v:"Since 2020, 7+ years, 30+ products, 6 banking apps, 4 Angular apps. Numbers come from the CV."},{k:"Never name employers",v:"Describe products by domain: a tax-filing platform, a fleet SaaS. No company or bank names."},{k:"English only",v:"One language, sentence case, no exclamation marks."}],pairs:[{no:"Elevating your digital experience",yes:"Angular platforms and multi-tenant SaaS"},{no:"Worked at a big bank",yes:"A tax-filing flow embedded in 6 banking apps"},{no:"Click here",yes:"View work"}],write:"Write",avoid:"Avoid"},a11y:{title:"Accessible by default",sub:"WCAG 2.1 AA is the floor, checked with axe in Playwright on every page. The system makes the accessible choice the easy one.",items:[{icon:"phosphorEye",k:"Contrast",v:"Text clears 4.5:1 on every surface; ink and ink-2 clear 7:1. --faint and lines are never text."},{icon:"phosphorCursorClick",k:"Targets",v:"Buttons 44px, inputs 46px, icon and small buttons 40px. Chips and tabs are the floor at 32px."},{icon:"phosphorSelection",k:"Focus",v:"2px ink outline, 3px offset, following the pill shape. Never removed."},{icon:"phosphorTreeStructure",k:"Landmarks",v:'Skip link, header nav "Primary", one main, footer. One h1, headings in order.'},{icon:"phosphorPause",k:"Reduced motion",v:"prefers-reduced-motion drops every transition and loop to its end state."},{icon:"phosphorStack",k:"Reduced transparency",v:"The glass nav becomes solid --surface when transparency is reduced."}],focus:"Focus ring",focusNote:"Press Tab to move through these. The ring is the real :focus-visible style.",target:"Target size",measured:"measured"}};export{e as a,a as b};
